export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}

function toAbsence(row: MemberAbsenceRow): MemberAbsence {
  return {
    orgId: brandId(row.orgId),
    userId: brandId(row.userId),
    delegateUserId:
      row.delegateUserId === null ? null : brandId(row.delegateUserId),
    startsAt: brandStamp(row.startsAt),
    endsAt: brandStamp(row.endsAt),
    note: row.note,
  };
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toAbsence(row) : null;
}

/** Insert or replace the member's single absence in this workspace. */
export async function upsertAbsence(input: {
  orgId: OrgId;
  userId: UserId;
  delegateUserId: UserId | null;
  startsAt: IsoTimestamp;
  endsAt: IsoTimestamp;
  note: string | null;
}): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toAbsence(row);
}

/** Clearing an absence that was never set is a no-op. */
export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * Drops `userId` as anyone's stand-in inside this workspace. The absence
 * itself stays, so coverage simply stops redirecting.
 */
export async function clearDelegates(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, userId),
      ),
    )
    .run();
}

/**
 * Decides, at the moment of an assignment, overdue sweep, or mention, whether
 * a member is away and who stands in for them.
 *
 * The window is half-open: the start counts, the end does not. Delegation is
 * never chained — a delegate who is themselves away still receives the work.
 * Taking an issue yourself is not redirected.
 */
import { parseIso } from "@/lib/date";
import * as memberRepo from "@/server/repositories/member-repository";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

/** True from `startsAt` inclusive until `endsAt` exclusive. */
export function isAway(absence: MemberAbsence, at: Date): boolean {
  const t = at.getTime();
  return (
    parseIso(absence.startsAt).getTime() <= t && t < parseIso(absence.endsAt).getTime()
  );
}

/** A scheduled absence is still readable; an ended one is not. */
export function isAbsenceOpen(absence: MemberAbsence, at: Date): boolean {
  return parseIso(absence.endsAt).getTime() > at.getTime();
}

async function isActiveMember(orgId: OrgId, userId: UserId): Promise<boolean> {
  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && member.status === "active";
}

/**
 * The stand-in for `userId` when they are away right now, or null when the
 * absence does not redirect (not away, no delegate, or the delegate has left).
 */
async function awayDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  if (!(await isActiveMember(orgId, userId))) return null;

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null) return null;
  if (!isAway(absence, at)) return null;
  if (absence.delegateUserId === userId) return null;
  if (!(await isActiveMember(orgId, absence.delegateUserId))) return null;

  return absence.delegateUserId;
}

/**
 * Assignee to store. Self-assignment is kept. Otherwise one hop to the
 * delegate, even when that delegate is away too.
 */
export async function resolveAssignmentTarget(
  orgId: OrgId,
  actorUserId: UserId,
  requestedAssigneeId: UserId | null,
  at: Date = new Date(),
): Promise<UserId | null> {
  if (requestedAssigneeId === null) return null;
  if (requestedAssigneeId === actorUserId) return requestedAssigneeId;
  return (await awayDelegate(orgId, requestedAssigneeId, at)) ?? requestedAssigneeId;
}

/** Overdue alerts follow the delegate when the stored assignee is away. */
export async function resolveOverdueRecipient(
  orgId: OrgId,
  assigneeId: UserId,
  at: Date = new Date(),
): Promise<UserId> {
  return (await awayDelegate(orgId, assigneeId, at)) ?? assigneeId;
}

/**
 * Mention alerts go to each mentioned member and, when they are away, also
 * to their delegate. One hop only; callers dedupe.
 */
export async function expandMentionAlerts(
  orgId: OrgId,
  mentionedUserIds: readonly UserId[],
  at: Date = new Date(),
): Promise<readonly UserId[]> {
  const recipients: UserId[] = [];
  for (const userId of mentionedUserIds) {
    recipients.push(userId);
    const delegate = await awayDelegate(orgId, userId, at);
    if (delegate !== null) recipients.push(delegate);
  }
  return recipients;
}

