/**
 * Members edit their own absence. Changing someone else's takes the same
 * permission as changing their role (`member:update_role`).
 */
function assertMayEditAbsence(actor: Actor, member: Member): void {
  if (actor.userId === member.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

function assertInterval(startsAt: IsoTimestamp, endsAt: IsoTimestamp): void {
  if (parseIso(endsAt).getTime() <= parseIso(startsAt).getTime()) {
    throw new Error("Absence end must be after the start");
  }
}

/**
 * Stores an absence, replacing any previous one for this member in this
 * workspace. Resolves to exactly the row that was written.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);
  const parsed = setAbsenceSchema.parse(input);

  const member = await requireActiveMember(parsed.orgId, parsed.userId);
  assertMayEditAbsence(actor, member);
  assertInterval(parsed.startsAt, parsed.endsAt);

  if (parsed.delegateUserId !== null) {
    if (parsed.delegateUserId === parsed.userId) {
      throw new Error("A member cannot delegate their absence to themselves");
    }
    await requireActiveMember(parsed.orgId, parsed.delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: parsed.orgId,
    userId: parsed.userId,
    delegateUserId: parsed.delegateUserId,
    startsAt: parsed.startsAt,
    endsAt: parsed.endsAt,
    note: parsed.note,
  });
}

/** Removes the absence. Succeeds when the member has none. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const member = await requireActiveMember(orgId, userId);
  assertMayEditAbsence(actor, member);
  await memberRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored absence until it ends, including one that has not started.
 * Null once it has ended, or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  const member = await requireActiveMember(orgId, userId);
  assertCan(actor, "member:read", memberResource(member));

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || !isAbsenceOpen(absence, new Date())) return null;
  return absence;
}

