import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { emit } from "@/lib/event-bus";
import { runOverdueIssueJob, resetOverdueTracking } from "@/server/jobs/overdue-issue-job";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, UserId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function window(startOffsetMs: number, endOffsetMs: number) {
  const now = Date.now();
  return {
    startsAt: new Date(now + startOffsetMs).toISOString(),
    endsAt: new Date(now + endOffsetMs).toISOString(),
  };
}

function absenceInput(
  tenant: Tenant,
  userId: UserId,
  overrides: Partial<{
    delegateUserId: UserId | null;
    startsAt: string;
    endsAt: string;
    note: string | null;
  }> = {},
) {
  const span = window(-60_000, 60_000);
  return setAbsenceSchema.parse({
    orgId: tenant.org.id,
    userId,
    delegateUserId: overrides.delegateUserId ?? null,
    startsAt: overrides.startsAt ?? span.startsAt,
    endsAt: overrides.endsAt ?? span.endsAt,
    note: overrides.note ?? null,
  });
}

async function mentions(tenant: Tenant, recipientId: UserId) {
  return listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["comment_mention"],
    limit: 25,
    cursor: null,
  });
}

describe("member absence", () => {
  it("stores, replaces, reads a future window, and clears", async () => {
    const tenant = await createTenant("absence-crud");
    const future = window(86_400_000, 172_800_000);
    const stored = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
        note: "out",
        ...future,
      }),
    );

    expect(stored).toMatchObject({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      note: "out",
    });

    const read = await memberService.getAbsence(
      tenant.actors.viewer,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(read?.delegateUserId).toBe(tenant.userIds.admin);

    const replaced = await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant, tenant.userIds.member, { note: "later", ...future }),
    );
    expect(replaced.delegateUserId).toBeNull();
    expect(replaced.note).toBe("later");

    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    await memberService.clearAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(
      await memberService.getAbsence(
        tenant.actors.member,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();
  });

  it("hides an absence once it has ended", async () => {
    const tenant = await createTenant("absence-ended");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, window(-10_000, -1_000)),
    );
    expect(
      await memberService.getAbsence(
        tenant.actors.member,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).toBeNull();
  });

  it("rejects a bad window, self-delegation, and outsiders", async () => {
    const tenant = await createTenant("absence-reject");
    const other = await createTenant("absence-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, tenant.userIds.member, window(5_000, 5_000)),
      ),
    ).rejects.toThrow(/after the start/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, tenant.userIds.member, {
          delegateUserId: tenant.userIds.member,
        }),
      ),
    ).rejects.toThrow(/themselves/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, tenant.userIds.admin),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        ...absenceInput(tenant, tenant.userIds.member),
        orgId: other.org.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.getAbsence(
        tenant.actors.owner,
        other.org.id,
        other.userIds.member,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        absenceInput(tenant, other.userIds.member),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, tenant.userIds.member, {
          delegateUserId: other.userIds.admin,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("removes the absence and drops delegations when the member leaves", async () => {
    const tenant = await createTenant("absence-remove");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, tenant.userIds.viewer, {
        delegateUserId: tenant.userIds.member,
      }),
    );

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    const viewerAbsence = await memberRepo.findAbsence(
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(viewerAbsence?.delegateUserId).toBeNull();
    expect(
      await memberRepo.findAbsence(tenant.org.id, tenant.userIds.member),
    ).toBeNull();
  });

  it("redirects assignment and creation once, but not self-assignment", async () => {
    const tenant = await createTenant("absence-assign");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant, tenant.userIds.admin, {
        delegateUserId: tenant.userIds.viewer,
      }),
    );

    const created = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Redirect create",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.admin);

    const self = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Keep mine",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(self.assigneeId).toBe(tenant.userIds.member);

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Reassign" }),
    );
    const assigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(assigned.assigneeId).toBe(tenant.userIds.admin);

    const chained = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });
    expect(chained.assigneeId).toBe(tenant.userIds.viewer);

    const taken = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(taken.assigneeId).toBe(tenant.userIds.member);
  });

  it("alerts the delegate for assignment, overdue, and mentions", async () => {
    const tenant = await createTenant("absence-alerts");
    await usageRepo.recomputeUsage(tenant.org.id);
    resetOverdueTracking();

    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Alert me" }),
    );
    await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    const assignedAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_assigned"],
      limit: 25,
      cursor: null,
    });
    const assignedMember = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["issue_assigned"],
      limit: 25,
      cursor: null,
    });
    expect(assignedAdmin.items).toHaveLength(1);
    expect(assignedMember.items).toHaveLength(0);

    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const overdue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late already mine",
        assigneeId: tenant.userIds.member,
        dueAt: "2020-01-01T00:00:00.000Z",
      }),
      tenant.userIds.owner,
      number,
    );
    await runOverdueIssueJob(new Date());

    const overdueAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_overdue"],
      limit: 25,
      cursor: null,
    });
    const overdueMember = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["issue_overdue"],
      limit: 25,
      cursor: null,
    });
    expect(overdue.assigneeId).toBe(tenant.userIds.member);
    expect(overdueAdmin.items).toHaveLength(1);
    expect(overdueMember.items).toHaveLength(0);

    const discussed = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Discuss" }),
    );
    await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: discussed.id,
      body: "ping",
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.admin],
    });

    expect((await mentions(tenant, tenant.userIds.member)).items).toHaveLength(1);
    expect((await mentions(tenant, tenant.userIds.admin)).items).toHaveLength(1);

    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: discussed.id,
      body: "again",
      mentionedUserIds: [tenant.userIds.member],
    });
    expect((await mentions(tenant, tenant.userIds.admin)).items).toHaveLength(1);
    expect((await mentions(tenant, tenant.userIds.member)).items).toHaveLength(2);
  });

  it("does not apply an absence from another workspace", async () => {
    const home = await createTenant("absence-home");
    const away = await createTenant("absence-away");
    await memberRepo.insertMember(away.org.id, home.userIds.member, "member", null);
    await memberService.setAbsence(
      { userId: home.userIds.member, orgId: away.org.id, role: "member" },
      absenceInput(away, home.userIds.member, {
        delegateUserId: away.userIds.admin,
      }),
    );

    const issue = await issueService.createIssue(
      home.actors.owner,
      issueInput(home.org.id, home.project.id, {
        title: "Stay home",
        assigneeId: home.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(home.userIds.member);
  });

  it("schema accepts the documented shape", () => {
    const parsed = setAbsenceSchema.parse({
      orgId: "01HZZZGGGGGGGGGGGGGGGGGGGG",
      userId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      startsAt: "2026-05-01T00:00:00.000Z",
      endsAt: "2026-05-02T00:00:00.000Z",
    });
    expect(parsed.delegateUserId).toBeNull();
    expect(parsed.note).toBeNull();
    expect(
      setAbsenceSchema.safeParse({
        orgId: "01HZZZGGGGGGGGGGGGGGGGGGGG",
        userId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
        startsAt: "2026-05-01T00:00:00.000Z",
        endsAt: "2026-05-02T00:00:00.000Z",
        note: "x".repeat(201),
      }).success,
    ).toBe(false);
  });

  it("emits the delegate as the assignee", async () => {
    const tenant = await createTenant("absence-event");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Event" }),
    );
    const seen: unknown[] = [];
    const { subscribe } = await import("@/lib/event-bus");
    const off = subscribe("issue.assigned", (payload) => {
      seen.push(payload);
    });
    await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    off();
    expect(seen[0]).toMatchObject({
      assigneeId: tenant.userIds.admin,
      previousAssigneeId: null,
    });
    void emit;
    void toIsoTimestamp;
    void OrgId;
  });
});
